import {normalizePDFURL} from './pdf-source.js';
import {compileDocument,validateContent} from './content-model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function openCaseEditor(api){
 const store=api.account;if(!store?.user){api.signIn();return;}
 if(!await store.isAdmin()){api.toast('This account does not have content administrator access.');return;}
 const original=api.snapshot();let draft=structuredClone(original),selected=api.initialDocument||null,page=0,dirty=false,busy=false,preview=false;
 const textVersions=new Map(original.documents.filter(d=>d.content).map(d=>[d.id,JSON.stringify(compileDocument(d.content).pages.map(p=>p.text))]));
 const dialog=document.createElement('dialog');dialog.className='case-editor';dialog.setAttribute('aria-label','Case editor');document.body.append(dialog);
 function setBusy(value){busy=value;for(const control of dialog.querySelectorAll('input,textarea,select,button'))control.disabled=value;}
 function status(message){dialog.querySelector('[role=status]').textContent=message;}
 const version=t=>t?{seconds:t.seconds,nanoseconds:t.nanoseconds}:null;
 const sameVersion=(a,b)=>JSON.stringify(a??null)===JSON.stringify(b??null);
 const active=()=>draft.documents.find(d=>d.id===selected);
 function read(){const form=dialog.querySelector('.case-fields');if(form){draft.name=form.querySelector('[name=title]').value;draft.description=form.querySelector('[name=description]').value;draft.questions=[...form.querySelectorAll('[data-question]')].map((n,i)=>{const q={...draft.questions[i],text:n.value},label=form.querySelector('[data-question-label="'+i+'"]').value;if(label||Object.hasOwn(q,'label'))q.label=label;return q;});}
 const d=active();if(d){d.title=dialog.querySelector('[name=docTitle]').value;d.category=dialog.querySelector('[name=category]').value;const pdfInput=dialog.querySelector('[name=pdfUrl]');if(pdfInput)d.pdfUrl=pdfInput.value;if(d.content){d.content.pages[page].markdown=dialog.querySelector('[name=markdown]').value;d.content.pages[page].label=dialog.querySelector('[name=pageLabel]').value;for(const n of dialog.querySelectorAll('[data-authority-name]'))d.content.references.find(r=>r.id===n.dataset.authorityName).name=n.value;}}}
 async function close(){if(busy)return;read();if(dirty&&!confirm('Close with unsaved changes? Save a draft first to keep them.'))return;if(preview)api.restore();dialog.close();dialog.remove();}
 function comparisonURL(d){try{return d.pdfUrl?.trim()?normalizePDFURL(d.pdfUrl):api.pdf(d.id);}catch{return '';}}
 function render(){const d=active();dialog.innerHTML=`<header><h2>Case editor</h2><button data-edit="close" aria-label="Close editor">Close</button></header><div class="editor-actions"><button data-edit="save">Save draft</button><button data-edit="preview">Preview draft</button><button data-edit="publish">Publish changes</button><span role="status">Drafts are private. Publishing updates public reading.</span></div><div class="editor-layout"><aside><button data-edit="case">Case details</button>${draft.documents.map(x=>`<button data-edit="document" data-id="${esc(x.id)}" class="${x.id===selected?'active':''}">${esc(x.title)}</button>`).join('')}<button data-edit="add-document">+ Add document</button></aside><main>${!d?`<div class="case-fields"><label>Case title<input name="title" value="${esc(draft.name)}"></label><label>Description / holding<textarea name="description">${esc(draft.description)}</textarea></label><h3>Questions presented</h3>${draft.questions.map((q,i)=>`<label><input aria-label="Question label" data-question-label="${i}" placeholder="Question ${i+1}" value="${esc(q.label||'')}"><textarea data-question="${i}">${esc(q.text)}</textarea><button data-edit="remove-question" data-index="${i}">Remove question</button></label>`).join('')}<button data-edit="add-question">Add question</button></div>`:`<label>Document title<input name="docTitle" value="${esc(d.title)}"></label><label>Section<select name="category">${['Certiorari','Merits','Amicus','Argument','Decision','Syllabus','Lower courts','Appendices','Other'].map(c=>`<option ${d.category===c?'selected':''}>${c}</option>`).join('')}</select></label><button data-edit="remove-document">Remove document from case</button>${d.id.startsWith('authored-')?`<label>PDF URL (optional)<input name="pdfUrl" type="url" placeholder="https://example.org/document.pdf" value="${esc(d.pdfUrl||'')}"></label><button data-edit="use-pdf">Use PDF link</button><p>Links stay on the source website. This does not upload a file or extract its text; paste or edit the reading text separately. Use a stable public PDF link.</p>`:''}${d.content?`<div class="editor-text-layout"><section><div class="editor-format"><button data-edit="bold"><b>B</b></button><button data-edit="italic"><i>I</i></button><button data-edit="underline"><u>U</u></button><select aria-label="Page" data-edit-page>${d.content.pages.map((p,i)=>`<option value="${i}" ${page===i?'selected':''}>Page ${esc(p.label||i+1)}</option>`).join('')}</select><button data-edit="add-page">Add page</button><button data-edit="remove-page">Remove page</button></div><label>Editable page marker<input name="pageLabel" value="${esc(d.content.pages[page].label)}"></label><label>Markdown text<textarea name="markdown" spellcheck="true">${esc(d.content.pages[page].markdown)}</textarea></label><p>Use **bold**, *italic*, &lt;u&gt;underline&lt;/u&gt; and [@authority-id]. PDF stays unchanged.</p><h3>Authorities</h3>${d.content.references.map(r=>`<div class="editor-authority"><span>[${r.number}]</span><input aria-label="Short authority name ${r.number}" data-authority-name="${esc(r.id)}" value="${esc(r.name)}"><button data-edit="insert-ref" data-id="${esc(r.id)}">Insert</button><button data-edit="edit-ref" data-id="${esc(r.id)}">Edit</button><button data-edit="remove-ref" data-id="${esc(r.id)}">Delete</button></div>`).join('')}<button data-edit="add-ref">Add authority</button></section>${comparisonURL(d)?`<section class="editor-pdf-comparison"><p><a data-open-original href="${esc(comparisonURL(d))}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">Open PDF in a new tab</a></p><p>Some websites block embedded viewing or cross-origin access. If the PDF is blank or unavailable here, open the link directly. HTTP links may be blocked on HTTPS pages.</p><iframe title="Original PDF for comparison" referrerpolicy="no-referrer" sandbox="allow-scripts allow-downloads" src="${esc(comparisonURL(d))}"></iframe></section>`:'<p>No original PDF is attached to this document.</p>'}</div>`:'<button data-edit="import-text">Create editable text version</button><p>This makes an independent copy of the reading text, including its numbered authorities. Future edits will not change the PDF.</p>'}`}</main></div>`;setBusy(busy);}
 dialog.addEventListener('input',()=>{dirty=true;});dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 dialog.addEventListener('change',e=>{if(e.target.matches('[data-edit-page]')){read();page=Number(e.target.value);render();}});
 dialog.addEventListener('click',async e=>{const b=e.target.closest('[data-edit]');if(!b||busy)return;const action=b.dataset.edit;
 try{if(action==='close'){await close();return;}if(['bold','italic','underline','insert-ref'].includes(action)){const t=dialog.querySelector('[name=markdown]'),start=t.selectionStart,end=t.selectionEnd,wrap={bold:['**','**'],italic:['*','*'],underline:['<u>','</u>']}[action];t.setRangeText(wrap?wrap[0]+t.value.slice(start,end)+wrap[1]:'[@'+b.dataset.id+']',start,end,'select');t.focus();dirty=true;return;}
 read();const d=active();
 if(action==='use-pdf'){d.pdfUrl=normalizePDFURL(d.pdfUrl);dirty=true;render();status('PDF link updated in this draft. Save or publish to keep it.');}else if(action==='case'){selected=null;render();}else if(action==='document'){selected=b.dataset.id;page=0;render();}
 else if(action==='add-document'){const id='authored-'+crypto.randomUUID();draft.documents.push({id,title:'Untitled document',category:'Other',content:{revision:crypto.randomUUID(),pages:[{label:'1',markdown:''}],references:[]}});selected=id;page=0;dirty=true;render();}
 else if(action==='remove-document'){if(confirm('Remove this document from the case collection? It will no longer appear in the reader or search after publication.')){draft.documents=draft.documents.filter(x=>x!==d);selected=null;dirty=true;render();}}
 else if(action==='add-question'){draft.questions.push({label:'Question '+(draft.questions.length+1),text:''});dirty=true;render();}
 else if(action==='remove-question'){draft.questions.splice(Number(b.dataset.index),1);dirty=true;render();}
 else if(action==='import-text'){setBusy(true);status('Preparing editable text…');d.content=await api.importDocument(d.id);dirty=true;render();}
 else if(action==='add-page'){d.content.pages.push({label:String(d.content.pages.length+1),markdown:''});page=d.content.pages.length-1;dirty=true;render();}
 else if(action==='remove-page'){if(d.content.pages.length===1)throw Error('Keep at least one page.');if(confirm('Remove this page and its text?')){d.content.pages.splice(page,1);page=Math.min(page,d.content.pages.length-1);dirty=true;render();}}
 else if(action==='add-ref'||action==='edit-ref'){const old=d.content.references.find(r=>r.id===b.dataset.id),name=prompt('Short authority name',old?.name||'');if(name===null)return;const citation=prompt('Full citation (used by existing hover previews)',old?.canonical||'');if(citation===null)return;if(old){old.name=name;old.canonical=citation;old.label=citation;}else d.content.references.push({id:'ref-'+crypto.randomUUID(),number:Math.max(0,...d.content.references.map(r=>r.number))+1,name,canonical:citation,label:citation,type:'case'});dirty=true;render();}
 else if(action==='remove-ref'){const r=d.content.references.find(r=>r.id===b.dataset.id);if(d.content.pages.some(p=>p.markdown.includes('[@'+r.id+']')))throw Error('Remove this authority’s text markers before deleting it.');d.content.references=d.content.references.filter(x=>x!==r);dirty=true;render();}
 else if(action==='save'||action==='publish'||action==='preview'){validateContent(draft);for(const x of draft.documents)if(x.content){const signature=JSON.stringify(compileDocument(x.content).pages.map(p=>p.text));if(textVersions.has(x.id)&&textVersions.get(x.id)!==signature)x.content.revision=crypto.randomUUID();textVersions.set(x.id,signature);}if(action==='preview'){api.apply(draft);preview=true;dialog.close();api.preview(()=>{dialog.showModal();render();},()=>{api.restore();preview=false;dialog.showModal();render();});return;}
 setBusy(true);status(action==='save'?'Saving draft…':'Publishing…');if(action==='save'){await store.saveContentDraft(draft.caseId,draft);dirty=false;status('Draft saved. Public content is unchanged.');}else if(confirm('Publish this case and its edited documents for everyone?')){await store.publishContent(draft.caseId,draft);api.apply(draft);api.commit?.();Object.assign(original,structuredClone(draft));preview=false;dirty=false;status('Published.');try{const latest=(await store.loadPublishedContent()).find(x=>x.id===draft.caseId);if(latest){draft=structuredClone(validateContent(latest.value));draft._basePublishedAt=version(latest.updatedAt);api.apply(draft);api.commit?.();Object.assign(original,structuredClone(draft));for(const d of draft.documents)if(d.content)textVersions.set(d.id,JSON.stringify(compileDocument(d.content).pages.map(p=>p.text)));if(selected&&!active())selected=null;render();}await store.saveContentDraft(draft.caseId,draft);status('Published. Latest public content is open.');}catch(error){status('Published, but the saved draft or publication baseline could not refresh. Reopen the editor before publishing again.');}}}
 }catch(error){status(error.message||'Could not save. Your changes remain open.');}finally{setBusy(false);}});
 render();dialog.showModal();setBusy(true);try{const saved=await store.loadContentDraft(original.caseId),published=(await store.loadPublishedContent()).find(x=>x.id===original.caseId);if(published?.value){const latest=validateContent(published.value);api.apply(latest);api.commit?.();Object.assign(original,structuredClone(latest));draft=structuredClone(latest);draft._basePublishedAt=version(published.updatedAt);for(const d of draft.documents)if(d.content)textVersions.set(d.id,JSON.stringify(compileDocument(d.content).pages.map(p=>p.text)));render();}if(saved?.value&&!dirty){const stamp=t=>t?.toMillis?.()??((t?.seconds||0)*1000);if(published&&(stamp(saved.updatedAt)<stamp(published.updatedAt)||!sameVersion(saved.value._basePublishedAt,version(published.updatedAt)))){status('A saved draft predates changes to the published case. The latest published version is open.');}else{draft=validateContent(saved.value);for(const d of draft.documents)if(d.content)textVersions.set(d.id,JSON.stringify(compileDocument(d.content).pages.map(p=>p.text)));render();status('Saved draft loaded.');}}if(selected&&!active())selected=null;if(active()&&!active().content){active().content=await api.importDocument(selected);dirty=true;render();status('Independent editable text is ready. Save a draft to keep it.');}if(saved?.ignoredReason||published?.ignoredReason)status(saved?.ignoredReason||published.ignoredReason);}catch(e){status('Could not load saved draft: '+e.message);}finally{setBusy(false);}
}
